CREATE DATABASE IF NOT EXISTS FLEET_APP COMMENT='{"origin":"sf_sit-is-fleet","name":"build-routing-solution","attributes":{"component":"data-contract-app-layer"}}';
CREATE SCHEMA IF NOT EXISTS FLEET_APP.BACKLOAD_MATCHING COMMENT='Stable logical layer for the backload pack (generated from data-model + entity-mapping).';

CREATE OR REPLACE VIEW FLEET_APP.BACKLOAD_MATCHING.VW_TRIPS_CURRENT AS
SELECT VEHICLE_ID, DESTINATION_LON, DESTINATION_LAT, DESTINATION_POI_ID, TRIP_END
FROM SYNTHETIC_DATASETS.UNIFIED.V_FACT_TRIPS_CURRENT
WHERE REGION = (SELECT REGION FROM FLEET_INTELLIGENCE.BACKLOAD_MATCHING.CONFIG LIMIT 1)
  AND VEHICLE_TYPE = (SELECT VEHICLE_TYPE FROM FLEET_INTELLIGENCE.BACKLOAD_MATCHING.CONFIG LIMIT 1);

CREATE OR REPLACE VIEW FLEET_APP.BACKLOAD_MATCHING.VW_POIS_CURRENT AS
SELECT LOCATION_ID, NAME, LAT, LNG
FROM SYNTHETIC_DATASETS.UNIFIED.V_DIM_POIS_CURRENT
WHERE REGION = (SELECT REGION FROM FLEET_INTELLIGENCE.BACKLOAD_MATCHING.CONFIG LIMIT 1);

CREATE OR REPLACE VIEW FLEET_APP.BACKLOAD_MATCHING.VW_FLEET_CURRENT AS
SELECT VEHICLE_ID, REGION, VEHICLE_TYPE, HOME_LOCATION_ID, BATTERY_RANGE_KM
FROM SYNTHETIC_DATASETS.UNIFIED.V_DIM_FLEET_CURRENT
WHERE REGION = (SELECT REGION FROM FLEET_INTELLIGENCE.BACKLOAD_MATCHING.CONFIG LIMIT 1)
  AND VEHICLE_TYPE = (SELECT VEHICLE_TYPE FROM FLEET_INTELLIGENCE.BACKLOAD_MATCHING.CONFIG LIMIT 1);

CREATE OR REPLACE VIEW FLEET_APP.BACKLOAD_MATCHING.VW_FREIGHT_OFFERS AS
SELECT OFFER_ID, SOURCE, REGION, PICKUP_POI_ID, DROPOFF_POI_ID,
       PICKUP_LON, PICKUP_LAT, DROPOFF_LON, DROPOFF_LAT,
       PICKUP_FROM_TS, PICKUP_TO_TS, PRODUCT, PRICE_USD, HAZMAT, LISTING_TEXT, POSTED_AT
FROM SYNTHETIC_DATASETS.UNIFIED.V_FACT_FREIGHT_OFFERS_CURRENT
WHERE REGION = (SELECT REGION FROM FLEET_INTELLIGENCE.BACKLOAD_MATCHING.CONFIG LIMIT 1);

CREATE OR REPLACE VIEW FLEET_APP.BACKLOAD_MATCHING.VW_VEHICLE_CLASS_PROFILE AS
SELECT * FROM OPENROUTESERVICE_APP.CORE.VEHICLE_CLASS_PROFILE;

CREATE OR REPLACE VIEW FLEET_APP.BACKLOAD_MATCHING.VW_PROPOSAL_DECISIONS AS
SELECT * FROM FLEET_INTELLIGENCE.BACKLOAD_MATCHING.PROPOSAL_DECISIONS;

CREATE OR REPLACE VIEW FLEET_APP.BACKLOAD_MATCHING.VW_CONFIG AS
SELECT * FROM FLEET_INTELLIGENCE.BACKLOAD_MATCHING.CONFIG;

CREATE OR REPLACE VIEW FLEET_APP.BACKLOAD_MATCHING.VW_TRAILERS AS
WITH last_drop AS (
  SELECT VEHICLE_ID,
         MAX_BY(DESTINATION_LON, TRIP_END) AS DROPOFF_LON,
         MAX_BY(DESTINATION_LAT, TRIP_END) AS DROPOFF_LAT,
         MAX_BY(DESTINATION_POI_ID, TRIP_END) AS DROPOFF_POI_ID,
         MAX(TRIP_END) AS LAST_TRIP_END
  FROM FLEET_APP.BACKLOAD_MATCHING.VW_TRIPS_CURRENT
  GROUP BY VEHICLE_ID
),
home_anchor AS (
  SELECT AVG(LAT) AS HOME_LAT, AVG(LNG) AS HOME_LON FROM FLEET_APP.BACKLOAD_MATCHING.VW_POIS_CURRENT
),
poi AS (
  SELECT LOCATION_ID, ANY_VALUE(NAME) AS NAME, ANY_VALUE(LAT) AS LAT, ANY_VALUE(LNG) AS LNG
  FROM FLEET_APP.BACKLOAD_MATCHING.VW_POIS_CURRENT GROUP BY LOCATION_ID
),
fleet AS (
  SELECT VEHICLE_ID, ANY_VALUE(REGION) AS REGION, ANY_VALUE(VEHICLE_TYPE) AS VEHICLE_TYPE,
         ANY_VALUE(HOME_LOCATION_ID) AS HOME_LOCATION_ID, ANY_VALUE(BATTERY_RANGE_KM) AS BATTERY_RANGE_KM
  FROM FLEET_APP.BACKLOAD_MATCHING.VW_FLEET_CURRENT GROUP BY VEHICLE_ID
),
cls AS (
  SELECT vcp.* FROM FLEET_APP.BACKLOAD_MATCHING.VW_VEHICLE_CLASS_PROFILE vcp
  WHERE vcp.VEHICLE_TYPE = (SELECT VEHICLE_TYPE FROM FLEET_APP.BACKLOAD_MATCHING.VW_CONFIG LIMIT 1)
)
SELECT
  f.VEHICLE_ID                                        AS TRAILER_ID,
  f.REGION                                            AS OPERATING_COUNTRY,
  COALESCE(h.NAME, 'Home Depot')                      AS HOME_DEPOT,
  COALESCE(h.LNG, (SELECT HOME_LON FROM home_anchor)) AS HOME_LON,
  COALESCE(h.LAT, (SELECT HOME_LAT FROM home_anchor)) AS HOME_LAT,
  f.VEHICLE_TYPE                                      AS CURRENT_LOAD,
  COALESCE(d.NAME, 'Drop-off')                        AS DROPOFF_CITY,
  ld.DROPOFF_LON                                      AS DROPOFF_LON,
  ld.DROPOFF_LAT                                      AS DROPOFF_LAT,
  ld.LAST_TRIP_END                                    AS ETA_TS,
  DATEDIFF('minute', CURRENT_TIMESTAMP(), ld.LAST_TRIP_END) AS ETA_MIN,
  'IN_TRANSIT'                                        AS STATUS,
  FALSE                                               AS HAZMAT_CERT,
  (SELECT PAYLOAD_KG_TYP FROM cls)::NUMBER            AS MAX_PAYLOAD_KG,
  NULLIF(f.BATTERY_RANGE_KM, 0)                       AS EV_RANGE_KM
FROM fleet f
JOIN last_drop ld ON ld.VEHICLE_ID = f.VEHICLE_ID
LEFT JOIN poi h ON h.LOCATION_ID = f.HOME_LOCATION_ID
LEFT JOIN poi d ON d.LOCATION_ID = ld.DROPOFF_POI_ID
WHERE EXISTS (SELECT 1 FROM cls);

CREATE OR REPLACE VIEW FLEET_APP.BACKLOAD_MATCHING.VW_EXTERNAL_OFFERS AS
WITH poi AS (
  SELECT LOCATION_ID, ANY_VALUE(NAME) AS NAME
  FROM FLEET_APP.BACKLOAD_MATCHING.VW_POIS_CURRENT GROUP BY LOCATION_ID
),
offers AS (
  SELECT * FROM FLEET_APP.BACKLOAD_MATCHING.VW_FREIGHT_OFFERS
  QUALIFY ROW_NUMBER() OVER (
    PARTITION BY OFFER_ID ORDER BY POSTED_AT DESC NULLS LAST, PICKUP_FROM_TS DESC NULLS LAST
  ) = 1
),
cls AS (
  SELECT vcp.* FROM FLEET_APP.BACKLOAD_MATCHING.VW_VEHICLE_CLASS_PROFILE vcp
  WHERE vcp.VEHICLE_TYPE = (SELECT VEHICLE_TYPE FROM FLEET_APP.BACKLOAD_MATCHING.VW_CONFIG LIMIT 1)
)
SELECT
  f.OFFER_ID,
  f.SOURCE,
  COALESCE(SUBSTR(f.REGION, 1, 2), 'US')   AS PICKUP_COUNTRY,
  COALESCE(SUBSTR(f.REGION, 1, 2), 'US')   AS DROPOFF_COUNTRY,
  COALESCE(p.NAME, 'Pickup')               AS PICKUP_CITY,
  f.PICKUP_LON, f.PICKUP_LAT,
  COALESCE(d.NAME, 'Dropoff')              AS DROPOFF_CITY,
  f.DROPOFF_LON, f.DROPOFF_LAT,
  f.PICKUP_FROM_TS, f.PICKUP_TO_TS,
  LEAST(
    (SELECT SHIPMENT_KG_MAX FROM cls),
    GREATEST(
      (SELECT SHIPMENT_KG_MIN FROM cls),
      ((SELECT SHIPMENT_KG_MIN FROM cls) + ABS(HASH(f.OFFER_ID)) % NULLIF(((SELECT SHIPMENT_KG_MAX FROM cls) - (SELECT SHIPMENT_KG_MIN FROM cls)), 0))::NUMBER
    )
  )                                        AS WEIGHT_KG,
  f.PRODUCT,
  f.PRICE_USD                              AS PRICE_EUR,
  f.HAZMAT,
  f.LISTING_TEXT
FROM offers f
LEFT JOIN poi p ON p.LOCATION_ID = f.PICKUP_POI_ID
LEFT JOIN poi d ON d.LOCATION_ID = f.DROPOFF_POI_ID
WHERE EXISTS (SELECT 1 FROM cls);

